 	r := newCentOS(config.ServerInfo{})
 	r.Distro = config.Distro{Family: "centos"}

package scan

import (
	"bufio"
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/models"
