func (o *redhatBase) parseOwnerPkgs(stdout string) ([]string, error) {
	var pkgNames []string
	seen := map[string]bool{}
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		if strings.HasSuffix(line, "Permission denied") ||
			strings.HasSuffix(line, "is not owned by any package") ||
			strings.HasSuffix(line, "No such file or directory") {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) != 5 {
			return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s", line)
		}
		if fields[1] != "(none)" {
			if _, err := strconv.ParseUint(fields[1], 10, 64); err != nil {
				return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s", line)
			}
		}
		pack, err := o.parseInstalledPackagesLine(line)
		if err != nil {
			return nil, err
		}
		if _, ok := o.Packages[pack.Name]; !ok {
			o.log.Debugf("rpm -qf package %s is not in installed packages", pack.Name)
			continue
		}
		if !seen[pack.Name] {
			pkgNames = append(pkgNames, pack.Name)
			seen[pack.Name] = true
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, xerrors.Errorf("Failed to scan rpm -qf output: %w", err)
	}
	return pkgNames, nil
}

