   570	func (o *redhatBase) parseOwnerPkgs(stdout string) ([]string, error) {
   571		var pkgNames []string
   572		seen := map[string]bool{}
   573		scanner := bufio.NewScanner(strings.NewReader(stdout))
   574		for scanner.Scan() {
   575			line := strings.TrimSpace(scanner.Text())
   576			if line == "" {
   577				continue
   578			}
   579			if strings.HasSuffix(line, "Permission denied") ||
   580				strings.HasSuffix(line, "is not owned by any package") ||
   581				strings.HasSuffix(line, "No such file or directory") {
   582				continue
   583			}
   584			fields := strings.Fields(line)
   585			if len(fields) != 5 {
   586				return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s", line)
   587			}
   588			if fields[1] != "(none)" {
   589				if _, err := strconv.ParseUint(fields[1], 10, 64); err != nil {
   590					return nil, xerrors.Errorf("Failed to parse rpm -qf line: %s", line)
   591				}
   592			}
   593			pack, err := o.parseInstalledPackagesLine(line)
   594			if err != nil {
   595				return nil, err
   596			}
   597			if _, ok := o.Packages[pack.Name]; !ok {
   598				o.log.Debugf("rpm -qf package %s is not in installed packages", pack.Name)
   599				continue
   600			}
   601			if !seen[pack.Name] {
   602				pkgNames = append(pkgNames, pack.Name)
   603				seen[pack.Name] = true
   604			}
   605		}
   606		if err := scanner.Err(); err != nil {
   607			return nil, xerrors.Errorf("Failed to scan rpm -qf output: %w", err)
   608		}
   609		return pkgNames, nil
   610	}
